-- Adminer 2.3.2 dump
SET NAMES utf8;
SET foreign_key_checks = 0;
SET time_zone = 'SYSTEM';
SET sql_mode = 'NO_AUTO_VALUE_ON_ZERO';

DROP TABLE IF EXISTS `car_brand`;
CREATE TABLE `car_brand` (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `img` varchar(255) NOT NULL,
  `firstletter` char(3) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=400 DEFAULT CHARSET=utf8 COMMENT='品牌';


DROP TABLE IF EXISTS `car_info`;
CREATE TABLE `car_info` (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `brand_id` int(10) NOT NULL COMMENT '品牌ID',
  `group_id` int(10) NOT NULL COMMENT '车系组ID',
  `series_id` int(10) NOT NULL COMMENT '车系id',
  `full_name` varchar(255) NOT NULL COMMENT '全称',
  `name` varchar(255) NOT NULL COMMENT '名字 ',
  `brand_name` varchar(255) NOT NULL COMMENT '品牌名称',
  `group_name` varchar(255) NOT NULL COMMENT '厂家名称',
  `series_name` varchar(255) NOT NULL COMMENT '车系名称',
  `state` int(10) NOT NULL,
  `minprice` int(10) NOT NULL COMMENT '最低价',
  `maxprice` int(10) NOT NULL COMMENT '最高价',
  `year` varchar(255) NOT NULL COMMENT '年份',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=1009621 DEFAULT CHARSET=utf8;


DROP TABLE IF EXISTS `car_series`;
CREATE TABLE `car_series` (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `group_id` int(10) NOT NULL DEFAULT '0' COMMENT '所属厂家',
  `brand_id` int(10) NOT NULL COMMENT '品牌名称',
  `full_name` varchar(255) NOT NULL COMMENT '全称',
  `name` varchar(255) NOT NULL COMMENT '名字',
  `firstletter` char(3) NOT NULL COMMENT '首字母',
  `seriesstate` int(10) NOT NULL DEFAULT '0',
  `seriesorder` int(10) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=5751 DEFAULT CHARSET=utf8 COMMENT='车系';


DROP TABLE IF EXISTS `car_series_group`;
CREATE TABLE `car_series_group` (
  `id` int(10) NOT NULL AUTO_INCREMENT,
  `brand_id` int(10) NOT NULL COMMENT '品牌名称',
  `name` varchar(255) NOT NULL COMMENT '名字',
  `firstletter` char(3) NOT NULL COMMENT '首字母',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=598 DEFAULT CHARSET=utf8 COMMENT='车系组';


